-- ============================================================
-- Mapa del campus UCC Santa Marta: planos y espacios de todos los bloques
-- Generado a partir de los DWG del levantamiento arquitectónico (bloques 1, 2A, 2B, 3, 4-5, 6, 7, 8
-- y plano general del campus, febrero de 2019):
-- imagen de cada planta y polígono de cada espacio (capa AREA/AREAS del plano),
-- en píxeles de la imagen (L.CRS.Simple: x desde la izquierda, y desde abajo).
--
-- Requiere V2__mapa_infraestructura.sql. Se puede ejecutar varias veces:
--   psql -U postgres -d ucc_orientacion -1 -f db/datos_mapa_campus.sql
--
-- Si ya existe un espacio con el mismo código, solo se le asigna el plano y el polígono.
-- Los espacios de servicio (aseo, bodegas, cuarto de bombas) quedan inactivos: el
-- administrador puede activarlos desde el panel.
-- ============================================================

SET client_min_messages = warning;

-- Versión anterior (solo Bloque 2): la Oficina 22 cambió de código OF-22 a OF-2-22.
UPDATE espacio SET codigo = 'OF-2-22' WHERE id = '5f100b4a-a842-5db7-8230-eb63e72a7bc4' AND codigo = 'OF-22'
  AND NOT EXISTS (SELECT 1 FROM espacio WHERE codigo = 'OF-2-22');

-- Plano Bloque 2A · Piso 1 (2200 x 1060 px)
INSERT INTO plano (id, nombre, edificio, piso, imagen, ancho, alto, activo) VALUES (
  '7fa047a5-dbce-5e79-8fcb-0b41c3121eaa', 'Bloque 2A · Piso 1', 'Bloque 2A', '1',
  'data:image/png;base64,',
  2200, 1060, TRUE)
ON CONFLICT (id) DO UPDATE SET nombre = EXCLUDED.nombre, edificio = EXCLUDED.edificio, piso = EXCLUDED.piso,
  imagen = EXCLUDED.imagen, ancho = EXCLUDED.ancho, alto = EXCLUDED.alto, actualizado_en = NOW();

